    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Insert if not exists
    VALUES (NEW.employee_id, NEW.first_name || ' ' || NEW.last_name, 'Employee', COALESCE(NEW.phone, 'N/A'))
    ON CONFLICT (employee_id) DO UPDATE
    SET
        partner_name = EXCLUDED.partner_name,
