    status character varying(20),
    late_hours numeric(4,2) DEFAULT 0,
    undertime_hours numeric(4,2) DEFAULT 0,
    is_holiday boolean DEFAULT false,
    holiday_type character varying(20),
    work_hours numeric(5,2) GENERATED ALWAYS AS (
CASE
    WHEN (time_out IS NULL) THEN (0)::numeric
    ELSE ((EXTRACT(epoch FROM (time_out - time_in)) / (3600)::numeric) - late_hours)
END) STORED,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_holiday_type CHECK (((holiday_type)::text = ANY (ARRAY[(NULL::character varying)::text, ('Regular'::character varying)::text, ('Special'::character varying)::text]))),
    CONSTRAINT chk_status CHECK (((status)::text = ANY (ARRAY[('Present'::character varying)::text, ('Absent'::character varying)::text, ('Late'::character varying)::text, ('Half-Day'::character varying)::text])))
);


