    CONSTRAINT chk_duration_days CHECK (((((employment_type)::text = 'Contractual'::text) AND ((typical_duration_days >= 30) AND (typical_duration_days <= 180))) OR (((employment_type)::text = 'Seasonal'::text) AND ((typical_duration_days >= 1) AND (typical_duration_days <= 29))) OR (((employment_type)::text = 'Regular'::text) AND (typical_duration_days IS NULL)))),
    CONSTRAINT chk_employment_types CHECK (((employment_type)::text = ANY (ARRAY[('Regular'::character varying)::text, ('Contractual'::character varying)::text, ('Seasonal'::character varying)::text]))),
    CONSTRAINT chk_salary_ranges CHECK (((((employment_type)::text = 'Regular'::text) AND (min_salary >= (0)::numeric) AND (max_salary >= min_salary)) OR (((employment_type)::text = ANY (ARRAY[('Contractual'::character varying)::text, ('Seasonal'::character varying)::text])) AND ((min_salary >= (500)::numeric) AND (min_salary <= (10000)::numeric)) AND (max_salary >= min_salary))))
);


