    approved_at timestamp without time zone,
    CONSTRAINT chk_approval_status CHECK (((approval_status)::text = ANY (ARRAY[('Pending'::character varying)::text, ('Approved'::character varying)::text, ('Rejected'::character varying)::text, ('Under Review'::character varying)::text]))),
    CONSTRAINT chk_status CHECK (((status)::text = ANY (ARRAY[('Draft'::character varying)::text, ('Submitted'::character varying)::text, ('Active'::character varying)::text, ('Completed'::character varying)::text, ('Canceled'::character varying)::text]))),
    CONSTRAINT employee_assignment_logic CHECK (((((approval_status)::text = 'Approved'::text) AND (employee_id IS NOT NULL)) OR ((approval_status)::text <> 'Approved'::text))),
    CONSTRAINT valid_allocation_period CHECK ((end_date >= start_date))
);


